/* Real FFmpeg/worker lifecycle checks; synthetic video generated by test_video.py. */
#include "pc5_video.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static void wait_import(Pc5VideoImport *job)
{
    int n = 0;
    while (!atomic_load(&job->done) && n++ < 1000) usleep(10000);
    assert(atomic_load(&job->done));
    pc5_video_import_end(job);
}
int main(int argc, char **argv)
{
    assert(argc == 5);
    const char *source = argv[1], *dest = argv[2], *fast = argv[3], *bad = argv[4];
    Pc5VideoImport job;
    assert(!pc5_video_import_start(&job, source, dest));
    wait_import(&job);
    assert(job.result == PC5_VIDEO_OK);
    struct stat before, after;
    assert(!stat(dest, &before) && before.st_size > 0);
    assert(!unlink(source));  /* Prove the imported copy needs no source drive. */
    Pc5Video video = { 0 };
    assert(!pc5_video_start(&video, dest));
    int frames = 0;
    for (int i = 0; i < 250; i++) {
        frames += pc5_video_poll(&video);
        if (atomic_load(&video.done)) break;
        usleep(5000);
    }
    assert(frames > 6 && !atomic_load(&video.done) && video.have && video.front);
    pc5_video_stop(&video);
    assert(!video.running && !video.front && !video.back);
    for (int i = 0; i < 3; i++) {
        assert(!pc5_video_start(&video, dest));
        usleep(20000);
        pc5_video_stop(&video);
    }
    assert(!pc5_video_import_start(&job, fast, dest));
    wait_import(&job);
    assert(job.result == PC5_VIDEO_FORMAT);
    assert(!stat(dest, &after) && before.st_size == after.st_size);
    assert(!pc5_video_import_start(&job, bad, dest));
    wait_import(&job);
    assert(job.result == PC5_VIDEO_FORMAT);
    assert(!stat(dest, &after) && before.st_size == after.st_size);
    assert(!pc5_video_import_start(&job, dest, bad));
    atomic_store(&job.stop, 1);
    wait_import(&job);
    assert(job.result == PC5_VIDEO_CANCELLED || job.result == PC5_VIDEO_OK);
    assert(!stat(dest, &after) && before.st_size == after.st_size);
    puts("video tests passed: H.264 1080p60 import, local copy, loop, stop/restart, >60fps rejection, bad input and cancellation");
    return 0;
}
